15	// DEVDESK-412 step 3: oci.Client (template tags and manifest) keeps its
16	// credentials on the origin they were meant for and is bounded in time. Server
17	// A plays the registry, server B another origin (same host, other port). The
18	// blob download is deliberately not covered here: it keeps its own policy
19	// (step 4), and these tests must not pin what happens to a redirected blob.
20	
21	const (
22		clientTestUser = "user"
23		clientTestPass = "S3CRETPW"
24	)
25	
26	// clientTestDigest is a well-formed layer digest, so the fixtures stay valid if
27	// the blob is later checked against the manifest.
28	var clientTestDigest = "sha256:" + strings.Repeat("a", 64)
29	
30	// clientOp is one public entry point of oci.Client that starts with a request
31	// the origin guard must cover.
32	type clientOp struct {
33		name string
34		run  func(c *Client) error
35	}
36	
37	func clientOps() []clientOp {
38		return []clientOp{
39			{"ListTags", func(c *Client) error {
40				_, err := c.ListTags("tpl")
41				return err
42			}},
43			{"DownloadTemplate", func(c *Client) error {
44				_, err := c.DownloadTemplate("tpl", "v1")
45				return err
46			}},
47		}
48	}
49	
50	// basicHeader is the Authorization value the client must send for the test
51	// credentials.
52	func basicHeader() string {
53		return "Basic " + base64.StdEncoding.EncodeToString([]byte(clientTestUser+":"+clientTestPass))
54	}
55	
56	// authsOf returns the Authorization header of every recorded hit whose
57	// "host path" contains pathPart, in arrival order.
58	func authsOf(l *hitLog, pathPart string) []string {
59		l.mu.Lock()
60		defer l.mu.Unlock()
61		var out []string
62		for i, h := range l.hits {
63			if strings.Contains(h, pathPart) {
64				out = append(out, l.auth[i])
65			}
66		}
67		return out
68	}
