70	func TestClientRefusesOffOriginRedirect(t *testing.T) {
71		for _, op := range clientOps() {
72			t.Run(op.name, func(t *testing.T) {
73				var bHits, aHits hitLog
74				b := recordingServer(t, &bHits)
75				a := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
76					aHits.record(r)
77					// Every request of the registry, tags or manifest, is sent to
78					// the other origin with a signed query.
79					http.Redirect(w, r, b.URL+"/x?sig=SECRET", http.StatusTemporaryRedirect)
80				}))
81				t.Cleanup(a.Close)
82	
83				c := NewClient(a.URL, clientTestUser, clientTestPass)
84				err := op.run(c)
85	
86				if !errors.Is(err, ErrOffOriginRedirect) {
87					t.Fatalf("err = %v, want errors.Is ErrOffOriginRedirect", err)
88				}
89				if n := bHits.count(); n != 0 {
90					t.Errorf("the other origin received %d requests, want 0", n)
91				}
92				if got := bHits.anyAuth(); got != "" {
93					t.Errorf("the other origin saw Authorization %q", got)
94				}
95				if got := authsOf(&aHits, ""); len(got) != 1 || got[0] != basicHeader() {
96					t.Errorf("registry Authorization headers = %q, want one Basic header", got)
97				}
98				for _, leak := range []string{"sig=SECRET", "SECRET", clientTestPass, "/x"} {
99					if strings.Contains(err.Error(), leak) {
100						t.Errorf("error %q leaks %q", err, leak)
101					}
102				}
103			})
104		}
105	}
