107	// clientTarGz serves as the layer the same-origin test downloads.
108	func clientTarGz(t *testing.T) []byte {
109		t.Helper()
110		data, err := io.ReadAll(buildTarGz(t, []tarEntry{{name: "Dockerfile", body: "FROM scratch\n"}}))
111		if err != nil {
112			t.Fatalf("reading fixture archive: %v", err)
113		}
114		return data
115	}
