117	func TestClientFollowsSameOriginRedirect(t *testing.T) {
118		archive := clientTarGz(t)
119	
120		cases := []struct {
121			op       clientOp
122			moved    string // a path the registry redirects to, same origin
123			fromPart string // path part of the first hop
124		}{
125			{clientOps()[0], "/v2/tpl/moved-tags", "/tags/list"},
126			{clientOps()[1], "/v2/tpl/moved-manifests/v1", "/manifests/"},
127		}
128		for _, tc := range cases {
129			t.Run(tc.op.name, func(t *testing.T) {
130				var hits hitLog
131				a := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
132					hits.record(r)
133					switch {
134					case strings.Contains(r.URL.Path, "/moved-tags"):
135						_, _ = fmt.Fprint(w, `{"tags":["v1"]}`)
136					case strings.Contains(r.URL.Path, "/moved-manifests/"):
137						_, _ = fmt.Fprintf(w, `{"layers":[{"mediaType":"application/vnd.oci.image.layer.v1.tar+gzip","digest":%q}]}`, clientTestDigest)
138					case strings.Contains(r.URL.Path, "/blobs/"):
139						_, _ = w.Write(archive)
140					default:
141						http.Redirect(w, r, tc.moved, http.StatusFound)
142					}
143				}))
144				t.Cleanup(a.Close)
145	
146				c := NewClient(a.URL, clientTestUser, clientTestPass)
147				if err := tc.op.run(c); err != nil {
148					t.Fatalf("same-origin redirect refused or failed: %v", err)
149				}
150	
151				first := authsOf(&hits, tc.fromPart)
152				second := authsOf(&hits, "/moved-")
153				if len(first) != 1 || len(second) != 1 {
154					t.Fatalf("hops: first %d, second %d, want 1 and 1", len(first), len(second))
155				}
156				if first[0] != basicHeader() {
157					t.Errorf("first hop Authorization = %q, want the Basic header", first[0])
158				}
159				if second[0] != basicHeader() {
160					t.Errorf("second hop Authorization = %q, want the Basic header", second[0])
161				}
162			})
163		}
164	}
