166	func TestNewClientIsBounded(t *testing.T) {
167		c := NewClient("http://registry.test", clientTestUser, clientTestPass)
168	
169		if templateClientTimeout != time.Minute {
170			t.Errorf("templateClientTimeout = %v, want 1 minute (decision Q2)", templateClientTimeout)
171		}
172		if c.httpClient.Timeout != templateClientTimeout {
173			t.Errorf("httpClient.Timeout = %v, want templateClientTimeout (%v)", c.httpClient.Timeout, templateClientTimeout)
174		}
175		if c.httpClient.CheckRedirect == nil {
176			t.Fatal("httpClient.CheckRedirect = nil, want the origin guard")
177		}
178	
179		// The hook is the guard itself, not just any function: another origin is
180		// refused, the same origin is accepted, without any network traffic.
181		first, _ := http.NewRequest(http.MethodGet, "http://registry.test/v2/tpl/manifests/v1", nil)
182		other, _ := http.NewRequest(http.MethodGet, "http://cdn.test/x", nil)
183		same, _ := http.NewRequest(http.MethodGet, "http://registry.test/elsewhere", nil)
184		if err := c.httpClient.CheckRedirect(other, []*http.Request{first}); !errors.Is(err, ErrOffOriginRedirect) {
185			t.Errorf("CheckRedirect(other origin) = %v, want ErrOffOriginRedirect", err)
186		}
187		if err := c.httpClient.CheckRedirect(same, []*http.Request{first}); err != nil {
188			t.Errorf("CheckRedirect(same origin) = %v, want nil", err)
189		}
190	}
