func TestProxyPortDefaults(t *testing.T) {
	for raw, want := range map[string]uint16{
		"http://p":          80,
		"https://p":         443,
		"socks5://p":        1080,
		"socks5h://p":       1080,
		"http://p:3128":     3128,
		"http://[::1]:8080": 8080,
	} {
		u, _ := url.Parse(raw)
